[Collection(PostgreSqlDatabaseFixture.CollectionName)]
public sealed class ArtworkFileE2ETests(PostgreSqlDatabaseFixture database)
{
    private static readonly byte[] Png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=");
    [Fact]public async Task CompleteArtworkFileFlowUsesRealMinioAndEnforcesSecurity()
    {
        await database.ResetAsync(TestContext.Current.CancellationToken);Guid companyId=Guid.NewGuid();await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){db.Companies.Add(Company.Create(companyId,"FILE_E2E","File E2E",DateTimeOffset.UtcNow).Value);await db.SaveChangesAsync(TestContext.Current.CancellationToken);}
        await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString,useObjectStorage:true,publicCompanyId:companyId.ToString());using HttpClient client=factory.CreateClient();using HttpRequestMessage bootstrap=new(HttpMethod.Post,"/api/v1/security/bootstrap"){Content=JsonContent.Create(new{companyId,username="file-admin",displayName="File Administrator",password="StrongFilePassword123"})};bootstrap.Headers.Add("X-Bootstrap-Secret","test-bootstrap-secret-123456789");(await client.SendAsync(bootstrap,TestContext.Current.CancellationToken)).EnsureSuccessStatusCode();LoginResult login=(await(await client.PostAsJsonAsync("/api/v1/auth/login",new{username="file-admin",password="StrongFilePassword123"},TestContext.Current.CancellationToken)).Content.ReadFromJsonAsync<LoginResult>(TestContext.Current.CancellationToken))!;await Send<object>(client,Request(HttpMethod.Post,"/api/v1/auth/me/company",login.AccessToken,null,new{companyId}));
        await AssertUploadStatus(client,login.AccessToken,companyId,"evil.exe","application/octet-stream","MZ"u8.ToArray(),HttpStatusCode.BadRequest);await AssertUploadStatus(client,login.AccessToken,companyId,"fake.png","image/png","not an image"u8.ToArray(),HttpStatusCode.BadRequest);await AssertUploadStatus(client,login.AccessToken,companyId,"mismatch.jpg","image/png",Png,HttpStatusCode.BadRequest);await AssertUploadStatus(client,login.AccessToken,companyId,"../escape.png","image/png",Png,HttpStatusCode.BadRequest);await AssertUploadStatus(client,login.AccessToken,companyId,"empty.png","image/png",[],HttpStatusCode.BadRequest);await AssertUploadStatus(client,login.AccessToken,companyId,"large.png","image/png",new byte[1048577],HttpStatusCode.BadRequest);using(MagickImage jpeg=new(MagickColors.Red,1,1)){UploadView acceptedJpeg=await Upload(client,login.AccessToken,companyId,"photo.jpg","image/jpeg",jpeg.ToByteArray(MagickFormat.Jpeg),null);Assert.Equal("image/jpeg",acceptedJpeg.MediaType);}
        ArtworkView artwork=await Send<ArtworkView>(client,Request(HttpMethod.Post,"/api/v1/artworks",login.AccessToken,companyId,new{code="ART-100",title="Print artwork",categoryCode="PRINT"}));UploadView upload1=await Upload(client,login.AccessToken,companyId,"design.png","image/png",Png,null);Assert.Equal(Convert.ToHexString(SHA256.HashData(Png)).ToLowerInvariant(),upload1.Sha256Hash);
        FileLinkView link=await Send<FileLinkView>(client,Request(HttpMethod.Post,$"/api/v1/files/{upload1.FileId}/links",login.AccessToken,companyId,new{fileVersionId=upload1.FileVersionId,entityType=0,entityId=artwork.Id,purpose=0}));Assert.Equal(artwork.Id,link.EntityId);ArtworkVersionView av1=await Send<ArtworkVersionView>(client,Request(HttpMethod.Post,$"/api/v1/artworks/{artwork.Id}/versions",login.AccessToken,companyId,new{fileVersionId=upload1.FileVersionId,notes="v1"}));Assert.Equal(1,av1.VersionNumber);
        bool thumbnails=false;for(int i=0;i<30&&!thumbnails;i++){await Task.Delay(200,TestContext.Current.CancellationToken);await using CoreDbContext verify=database.CreateAdministrationCoreDbContext();thumbnails=await verify.FileDerivatives.IgnoreQueryFilters().AnyAsync(x=>x.SourceFileVersionId==upload1.FileVersionId,TestContext.Current.CancellationToken);}Assert.True(thumbnails);
        bool webVariant=false;for(int i=0;i<60&&!webVariant;i++){await Task.Delay(200,TestContext.Current.CancellationToken);await using CoreDbContext verify=database.CreateAdministrationCoreDbContext();webVariant=await verify.FileDerivatives.IgnoreQueryFilters().AnyAsync(x=>x.SourceFileVersionId==upload1.FileVersionId&&x.DerivativeType==FileDerivativeType.Web,TestContext.Current.CancellationToken);}Assert.True(webVariant);
        using(HttpResponseMessage urlResponse=await client.SendAsync(Request(HttpMethod.Get,$"/api/v1/artworks/{artwork.Id}/thumbnail-url?variant=thumb",login.AccessToken,companyId),TestContext.Current.CancellationToken)){urlResponse.EnsureSuccessStatusCode();DerivativeUrlView? urlView=await urlResponse.Content.ReadFromJsonAsync<DerivativeUrlView>(TestJson.ApiOptions,TestContext.Current.CancellationToken);Assert.NotNull(urlView);Assert.Equal("image/png",urlView!.MediaType);using HttpClient anonymous=new();byte[] direct=await anonymous.GetByteArrayAsync(urlView.Url,TestContext.Current.CancellationToken);Assert.Equal(137,direct[0]);Assert.Equal(80,direct[1]);Assert.Equal(78,direct[2]);}
        using(HttpResponseMessage originalUrl=await client.SendAsync(Request(HttpMethod.Get,$"/api/v1/artworks/{artwork.Id}/original-url",login.AccessToken,companyId),TestContext.Current.CancellationToken)){originalUrl.EnsureSuccessStatusCode();DerivativeUrlView? view=await originalUrl.Content.ReadFromJsonAsync<DerivativeUrlView>(TestJson.ApiOptions,TestContext.Current.CancellationToken);Assert.NotNull(view);using HttpClient anonymous=new();using HttpResponseMessage direct=await anonymous.GetAsync(view!.Url,TestContext.Current.CancellationToken);direct.EnsureSuccessStatusCode();Assert.Equal("image/png",direct.Content.Headers.ContentType?.MediaType);}
        using(HttpResponseMessage thumb=await client.SendAsync(Request(HttpMethod.Get,$"/api/v1/artworks/{artwork.Id}/thumbnail",login.AccessToken,companyId),TestContext.Current.CancellationToken)){thumb.EnsureSuccessStatusCode();Assert.True(thumb.Headers.TryGetValues("Cache-Control",out IEnumerable<string>? cacheControl));Assert.Contains(cacheControl,v=>v.Contains("immutable",StringComparison.Ordinal));}
        using(HttpResponseMessage publicCatalog=await client.SendAsync(new HttpRequestMessage(HttpMethod.Get,"/api/v1/public/catalog?pageSize=10"),TestContext.Current.CancellationToken)){publicCatalog.EnsureSuccessStatusCode();JsonElement catalogPage=await publicCatalog.Content.ReadFromJsonAsync<JsonElement>(TestJson.ApiOptions,TestContext.Current.CancellationToken);Assert.True(catalogPage.GetProperty("total").GetInt64()>=1);JsonElement firstItem=catalogPage.GetProperty("items").EnumerateArray().First();Assert.Equal(artwork.Id,firstItem.GetProperty("id").GetGuid());string? previewUrl=firstItem.GetProperty("previewUrl").GetString();Assert.True(!string.IsNullOrWhiteSpace(previewUrl),"previewUrl missing; item="+firstItem.GetRawText());Assert.Contains("barang-phase10-tests-public",previewUrl);using HttpClient anonymous=new();using HttpResponseMessage previewFetch=await anonymous.GetAsync(previewUrl,TestContext.Current.CancellationToken);previewFetch.EnsureSuccessStatusCode();}
        using(HttpResponseMessage publicDetail=await client.SendAsync(new HttpRequestMessage(HttpMethod.Get,$"/api/v1/public/catalog/{artwork.Id}"),TestContext.Current.CancellationToken)){publicDetail.EnsureSuccessStatusCode();JsonElement detail=await publicDetail.Content.ReadFromJsonAsync<JsonElement>(TestJson.ApiOptions,TestContext.Current.CancellationToken);Assert.Equal("ART-100",detail.GetProperty("code").GetString());Assert.False(string.IsNullOrWhiteSpace(detail.GetProperty("thumbnailUrl").GetString()));}
        byte[]pdf="%PDF-1.4\n1 0 obj\n<<>>\nendobj\n%%EOF"u8.ToArray();UploadView upload2=await Upload(client,login.AccessToken,companyId,"design.pdf","application/pdf",pdf,upload1.FileId);ArtworkVersionView av2=await Send<ArtworkVersionView>(client,Request(HttpMethod.Post,$"/api/v1/artworks/{artwork.Id}/versions",login.AccessToken,companyId,new{fileVersionId=upload2.FileVersionId,notes="v2"}));Assert.Equal(2,av2.VersionNumber);ArtworkVersionView[]versions=await Send<ArtworkVersionView[]>(client,Request(HttpMethod.Get,$"/api/v1/artworks/{artwork.Id}/versions",login.AccessToken,companyId));Assert.Equal(upload1.FileVersionId,versions[0].FileVersionId);Assert.Equal(upload2.FileVersionId,versions[1].FileVersionId);
        using(HttpResponseMessage duplicate=await UploadRaw(client,login.AccessToken,companyId,"duplicate.png","image/png",Png,null)){Assert.Equal(HttpStatusCode.Conflict,duplicate.StatusCode);}using(HttpResponseMessage download=await client.SendAsync(Request(HttpMethod.Get,$"/api/v1/files/{upload1.FileId}/versions/{upload1.FileVersionId}/download",login.AccessToken,companyId),TestContext.Current.CancellationToken)){download.EnsureSuccessStatusCode();Assert.Equal(Png,await download.Content.ReadAsByteArrayAsync(TestContext.Current.CancellationToken));}
        (string Name,string Media,MagickFormat Format)[] rasterFormats=[("photo.gif","image/gif",MagickFormat.Gif),("photo.webp","image/webp",MagickFormat.WebP),("photo.bmp","image/bmp",MagickFormat.Bmp),("photo.tiff","image/tiff",MagickFormat.Tiff)];
        foreach((string Name,string Media,MagickFormat Format) raster in rasterFormats){using MagickImage image=new(MagickColors.Blue,2,2);UploadView uploaded=await Upload(client,login.AccessToken,companyId,raster.Name,raster.Media,image.ToByteArray(raster.Format),null);Assert.Equal(raster.Media,uploaded.MediaType);}
        artwork=await Send<ArtworkView>(client,Request(HttpMethod.Post,$"/api/v1/artworks/{artwork.Id}/archive",login.AccessToken,companyId,new{archived=true,version=(await Send<ArtworkView>(client,Request(HttpMethod.Get,$"/api/v1/artworks/{artwork.Id}",login.AccessToken,companyId))).Version}));Assert.True(artwork.IsArchived);Assert.DoesNotContain(await Send<ArtworkOption[]>(client,Request(HttpMethod.Get,"/api/v1/artworks/options",login.AccessToken,companyId)),x=>x.Id==artwork.Id);Assert.Equal(2,(await Send<ArtworkVersionView[]>(client,Request(HttpMethod.Get,$"/api/v1/artworks/{artwork.Id}/versions",login.AccessToken,companyId))).Length);
        Guid other=Guid.NewGuid();await using(CoreDbContext setup=database.CreateAdministrationCoreDbContext()){setup.Companies.Add(Company.Create(other,"FILE_OTHER","Other",DateTimeOffset.UtcNow).Value);await setup.SaveChangesAsync(TestContext.Current.CancellationToken);}using(HttpResponseMessage denied=await client.SendAsync(Request(HttpMethod.Get,$"/api/v1/files/{upload1.FileId}/versions/{upload1.FileVersionId}/download",login.AccessToken,other),TestContext.Current.CancellationToken)){Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);}using(HttpResponseMessage invalidLink=await client.SendAsync(Request(HttpMethod.Post,$"/api/v1/files/{upload1.FileId}/links",login.AccessToken,companyId,new{fileVersionId=upload1.FileVersionId,entityType=99,entityId=artwork.Id,purpose=0}),TestContext.Current.CancellationToken)){Assert.Equal(HttpStatusCode.NotFound,invalidLink.StatusCode);}using(HttpResponseMessage noDelete=await client.SendAsync(Request(HttpMethod.Delete,$"/api/v1/files/{upload1.FileId}",login.AccessToken,companyId),TestContext.Current.CancellationToken)){Assert.Equal(HttpStatusCode.MethodNotAllowed,noDelete.StatusCode);}await using(CoreDbContext audit=database.CreateAdministrationCoreDbContext()){Assert.True(await audit.AuditEvents.IgnoreQueryFilters().AnyAsync(x=>x.CompanyId==companyId&&x.Action=="file.thumbnail.created",TestContext.Current.CancellationToken));FileVersion stored=await audit.FileVersions.IgnoreQueryFilters().SingleAsync(x=>x.Id==upload1.FileVersionId,TestContext.Current.CancellationToken);Assert.StartsWith($"companies/{companyId:N}/files/{upload1.FileId:N}/versions/",stored.StorageKey,StringComparison.Ordinal);Assert.DoesNotContain("design.png",stored.StorageKey,StringComparison.OrdinalIgnoreCase);await audit.Database.ExecuteSqlRawAsync("DELETE FROM barang.role_permissions WHERE permission_id=(SELECT id FROM barang.permissions WHERE code='file.read')",TestContext.Current.CancellationToken);}using(HttpResponseMessage forbidden=await client.SendAsync(Request(HttpMethod.Get,$"/api/v1/files/{upload1.FileId}",login.AccessToken,companyId),TestContext.Current.CancellationToken)){Assert.Equal(HttpStatusCode.Forbidden,forbidden.StatusCode);}await Send<object>(client,Request(HttpMethod.Post,"/api/v1/auth/logout",login.AccessToken,null));
    }
    private static async Task<UploadView>Upload(HttpClient c,string token,Guid company,string name,string type,byte[]bytes,Guid?fileId){using HttpResponseMessage response=await UploadRaw(c,token,company,name,type,bytes,fileId);response.EnsureSuccessStatusCode();return(await response.Content.ReadFromJsonAsync<UploadView>(TestContext.Current.CancellationToken))!;}
    private static Task<HttpResponseMessage>UploadRaw(HttpClient c,string token,Guid company,string name,string type,byte[]bytes,Guid?fileId){MultipartFormDataContent form=new();ByteArrayContent content=new(bytes);content.Headers.ContentType=new MediaTypeHeaderValue(type);form.Add(content,"file",name);form.Add(new StringContent("client-hash-must-be-ignored"),"sha256");if(fileId is not null)form.Add(new StringContent(fileId.Value.ToString()),"fileId");HttpRequestMessage request=Request(HttpMethod.Post,"/api/v1/files/upload",token,company);request.Content=form;return c.SendAsync(request,TestContext.Current.CancellationToken);}
    private static async Task AssertUploadStatus(HttpClient c,string token,Guid company,string name,string type,byte[]bytes,HttpStatusCode expected){using HttpResponseMessage response=await UploadRaw(c,token,company,name,type,bytes,null);Assert.True(expected==response.StatusCode,$"{name}: expected {expected} but got {response.StatusCode}: {await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken)}");}
    private static HttpRequestMessage Request(HttpMethod method,string path,string token,Guid?company,object?body=null){HttpRequestMessage request=new(method,path);request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);if(company is not null)request.Headers.Add("X-Company-ID",company.ToString());if(body is not null)request.Content=JsonContent.Create(body);return request;}private static async Task<T>Send<T>(HttpClient c,HttpRequestMessage request){using(request){using HttpResponseMessage response=await c.SendAsync(request,TestContext.Current.CancellationToken);response.EnsureSuccessStatusCode();if(typeof(T)==typeof(object))return default!;return(await response.Content.ReadFromJsonAsync<T>(TestContext.Current.CancellationToken))!;}}
}
